import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"托尼·尼斯利 (Tony Nicely)","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/托尼·尼斯利.md","filePath":"04_people/托尼·尼斯利.md"}'),o={name:"04_people/托尼·尼斯利.md"};function i(h,t,d,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="托尼·尼斯利-tony-nicely" tabindex="-1">托尼·尼斯利 (Tony Nicely) <a class="header-anchor" href="#托尼·尼斯利-tony-nicely" aria-label="Permalink to &quot;托尼·尼斯利 (Tony Nicely)&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>全名</td><td>Anthony George Nicely</td></tr><tr><td>出生</td><td>1944年</td></tr><tr><td>公司</td><td><a href="/03_companies/GEICO.html">GEICO</a></td></tr><tr><td>职位</td><td>CEO</td></tr><tr><td>任期</td><td>2003年—2016年</td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="加入-geico" tabindex="-1">加入 GEICO <a class="header-anchor" href="#加入-geico" aria-label="Permalink to &quot;加入 GEICO&quot;">​</a></h3><ul><li><strong>1962年</strong>：18岁加入 <a href="/03_companies/GEICO.html">GEICO</a>，从基层客服做起</li><li><strong>1967年</strong>：转任精算师，开始积累保险核心业务能力</li><li><strong>1993年</strong>：晋升为执行副总裁（Executive Vice President）</li><li><strong>2003年</strong>：接替前任，正式担任 <a href="/03_companies/GEICO.html">GEICO</a> CEO</li></ul><h3 id="ceo-任期-2003—2016" tabindex="-1">CEO 任期（2003—2016） <a class="header-anchor" href="#ceo-任期-2003—2016" aria-label="Permalink to &quot;CEO 任期（2003—2016）&quot;">​</a></h3><ul><li>任职期间，<a href="/03_companies/GEICO.html">GEICO</a> 从美国<strong>第三大</strong>汽车保险公司攀升至<strong>第二大</strong></li><li>推动公司数字化转型，提升运营效率</li><li>保费收入和市场份额持续大幅增长</li><li><strong>2016年</strong>：退休，结束在 GEICO 长达54年的职业生涯</li></ul><h3 id="荣誉" tabindex="-1">荣誉 <a class="header-anchor" href="#荣誉" aria-label="Permalink to &quot;荣誉&quot;">​</a></h3><ul><li><strong>2012年</strong>：荣获伯克希尔·哈撒韦年度最佳经理奖（Berkshire Hathaway&#39;s Annual Best Manager Award），成为巴菲特多次公开表彰的明星经理人之一</li></ul><h2 id="与伯克希尔的关系" tabindex="-1">与伯克希尔的关系 <a class="header-anchor" href="#与伯克希尔的关系" aria-label="Permalink to &quot;与伯克希尔的关系&quot;">​</a></h2><p>托尼·尼斯利是巴菲特最为倚重的保险子公司管理者之一。在他的领导下，<a href="/03_companies/GEICO.html">GEICO</a> 成为伯克希尔保险帝国中最具成长性的业务板块之一。巴菲特多次在股东信中肯定 GEICO 的业绩增长，并将尼斯利视为最优秀的职业经理人典型。</p><p>尼斯利的前任是<a href="/04_people/杰克·伯恩.html">杰克·伯恩</a>——后者在1970年代将 GEICO 从破产边缘拯救回来，为尼斯利后续的腾飞奠定了坚实基础。</p><p>另一位与尼斯利同期的伯克希尔保险核心人物是<a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a>（Ajit Jain），后者执掌伯克希尔再保险业务，两人共同构成巴菲特保险帝国的一线将帅。</p><h2 id="主要成就" tabindex="-1">主要成就 <a class="header-anchor" href="#主要成就" aria-label="Permalink to &quot;主要成就&quot;">​</a></h2><table tabindex="0"><thead><tr><th>成就</th><th>说明</th></tr></thead><tbody><tr><td>市场份额跃升</td><td>领导 GEICO 从美国第三大升至第二大汽车保险公司</td></tr><tr><td>数字化转型</td><td>推动在线投保、电话直销等现代化渠道建设</td></tr><tr><td>规模增长</td><td>任职13年期间，保费收入增长数倍</td></tr><tr><td>人才培养</td><td>打造了一支高效的 GEICO 管理团队</td></tr></tbody></table><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><blockquote><p>&quot;托尼·尼斯利是一位非凡的保险经营者。他在 GEICO 的卓越表现证明了他无与伦比的管理才能和对业务的深刻理解。&quot; —— 伯克希尔·哈撒韦股东信</p></blockquote><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>2006年、2007年、2008年、2009年、2010年、2011年、2012年、2013年、2014年、2015年、2016年</p><hr><p><em>最后更新：2026-04-12</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=托尼·尼斯利在2005年股东信中的原话">2005年：完整翻译|/01_letters/2005年/翻译</a></li><li><a href="/search.html?q=托尼·尼斯利在1995年股东信中的原话">1995年：完整翻译|/01_letters/1995年/翻译</a></li></ul>',25)])])}const _=a(o,[["render",i]]);export{p as __pageData,_ as default};
